css:
html[data-theme="dark"]{--bg:#02050b;--bg2:#050b14;--panel:#08111d;--panel2:#0a1523;--panel3:#0d1b2b;--line:#183149;--line2:#28506f;--text:#f3f8ff;--muted:#8299ad;--accent:#49cfff;--accent2:#8e8bff;--ok:#4de0a0;--warn:#ffbf66;--bad:#ff727c;--blue:#64a9ff;--bar:rgba(2,5,11,.9);--shadow:0 22px 58px rgba(0,0,0,.42),inset 0 1px 0 rgba(255,255,255,.025);--grid:rgba(73,207,255,.018)}
html[data-theme="light"]{--bg:#edf2f4;--bg2:#f7fafb;--panel:#ffffff;--panel2:#f2f6f8;--panel3:#eaf1f4;--line:#cad8de;--line2:#aac0ca;--text:#17232c;--muted:#647985;--accent:#087f9c;--accent2:#6749b7;--ok:#138a59;--warn:#a95f00;--bad:#c84141;--blue:#246eb2;--bar:rgba(247,250,251,.94);--shadow:0 12px 30px rgba(37,63,75,.1);--grid:rgba(8,127,156,.045)}
*{box-sizing:border-box}
html{min-height:100%;background:var(--bg)}
body{font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",Arial,sans-serif;margin:0 auto;padding:0 18px 118px;color:var(--text);-webkit-text-size-adjust:100%;line-height:1.45;max-width:1440px;overflow-x:hidden;background:linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px),radial-gradient(circle at 82% -8%,rgba(73,207,255,.15),transparent 32%),radial-gradient(circle at 4% 34%,rgba(142,139,255,.09),transparent 28%),linear-gradient(180deg,var(--bg),var(--bg2) 60%,var(--bg));background-size:28px 28px,28px 28px,auto,auto,auto}
html[data-theme="light"],html[data-theme="light"] body{background:#fff}
button,input,select{font:inherit;max-width:100%}button{color:inherit}
h1{font-size:18px;margin:0;font-weight:900;letter-spacing:-.025em}h2{font-size:13px;margin:0;text-transform:uppercase;letter-spacing:.08em;font-weight:850}h3{font-size:11px;margin:14px 0 7px;padding-top:10px;color:var(--accent2);border-top:1px solid var(--line);text-transform:uppercase;letter-spacing:.08em}h2+h3{border-top:0;padding-top:0;margin-top:2px}
.topbar{position:relative;z-index:20;margin:0 -18px 12px;padding:18px 18px 14px;background:linear-gradient(180deg,var(--bar),rgba(2,5,11,.55));border-bottom:1px solid rgba(73,207,255,.16);backdrop-filter:blur(22px)}
html[data-theme="light"] .topbar{background:linear-gradient(180deg,#fff 0%,#f7fafb 58%,#f3f6f8 100%);border-bottom-color:rgba(8,127,156,.12)}
.topline,.brand,.topActions,.commandRow,.navPills,.cardHead,.cardTitle,.profileMeta,.busTop{display:flex;align-items:center}.topline{position:relative;justify-content:space-between;gap:14px}.brand{gap:12px;min-width:0}.brandMark{width:42px;height:42px;min-width:42px;display:grid;place-items:center;border-radius:13px;border:1px solid rgba(73,207,255,.45);background:linear-gradient(145deg,rgba(73,207,255,.2),rgba(142,139,255,.08));color:var(--accent);font-size:13px;font-weight:950;box-shadow:0 0 30px rgba(73,207,255,.13),inset 0 1px 0 rgba(255,255,255,.08)}.brandText{position:absolute;left:50%;min-width:0;transform:translateX(-50%);text-align:center}.brandText h1{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.subtitle{margin-top:3px;color:var(--muted);font-size:10px;letter-spacing:.04em}.pageHeading{margin:16px 0 0}.pageHeading h2{font-size:22px;letter-spacing:-.025em;text-transform:none}.pageHeading p{margin:4px 0 0;color:var(--muted);font-size:11px}.topActions{gap:7px}.commandRow{gap:10px;padding-top:10px}.navPills{gap:7px;overflow-x:auto;scrollbar-width:none}.navPills::-webkit-scrollbar{display:none}
button,.linkbtn{min-height:38px;border:1px solid var(--line2);border-radius:6px;background:var(--panel2);color:var(--text);padding:8px 11px;cursor:pointer;font-size:11px;font-weight:800;text-decoration:none;transition:.16s ease}button:hover,.linkbtn:hover{border-color:var(--accent);color:var(--accent)}button.warn:hover{border-color:var(--bad);color:var(--bad)}button.ghost{background:transparent}.topActions .warn{color:var(--bad);border-color:rgba(255,110,110,.35);background:rgba(255,110,110,.08)}.navPill{flex:0 0 auto;min-height:34px;padding:7px 12px;border-radius:999px;background:var(--panel2);color:var(--muted)}.navPill.active{color:var(--accent);border-color:rgba(70,217,255,.5);background:rgba(70,217,255,.1)}.linkbtn{display:none}
.result{display:none;min-width:0;margin-left:auto;color:var(--warn);font-size:10px;text-align:right}.result:not(:empty){display:block}.statusError{color:var(--bad)}.statusError.warning{color:var(--warn)}
.page{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:14px;min-width:0}.appPage>.card{grid-column:span 12}.card{grid-column:span 6;min-width:0;max-width:100%;padding:16px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(155deg,rgba(13,27,43,.98),rgba(6,14,24,.98));box-shadow:var(--shadow);position:relative;overflow:hidden}.card:before{content:"";position:absolute;inset:0 0 auto;height:1px;background:linear-gradient(90deg,transparent,rgba(73,207,255,.24),transparent);pointer-events:none}.wide,.span-12{grid-column:span 12}.span-8{grid-column:span 8}.span-7{grid-column:span 7}.span-6{grid-column:span 6}.span-5{grid-column:span 5}.span-4{grid-column:span 4}html[data-theme="light"] .card{background:var(--panel)}
.cardHead{align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px}.cardTitle{align-items:flex-start;gap:11px}.cardTitle i{display:grid;place-items:center;width:36px;height:36px;min-width:36px;border-radius:11px;border:1px solid color-mix(in srgb,var(--card-accent,var(--accent)) 45%,transparent);background:color-mix(in srgb,var(--card-accent,var(--accent)) 12%,transparent);box-shadow:0 0 20px color-mix(in srgb,var(--card-accent,var(--accent)) 12%,transparent);color:var(--card-accent,var(--accent));font-size:17px;font-style:normal;font-weight:900}.cardTitle h2{color:var(--text);font-size:14px;letter-spacing:.025em;text-transform:none}.cardTitle p{margin:5px 0 0;color:var(--muted);font-size:10px;line-height:1.5}.tag{flex:0 0 auto;padding:5px 8px;border:1px solid color-mix(in srgb,var(--card-accent,var(--accent)) 35%,var(--line));border-radius:999px;color:var(--card-accent,var(--accent));background:color-mix(in srgb,var(--card-accent,var(--accent)) 8%,transparent);font-size:9px;letter-spacing:.03em}
.card.collapsible>.cardHead{cursor:pointer;user-select:none}.card.collapsible>.cardHead:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:6px}.card.collapsible.collapsed>.cardHead{margin-bottom:0}.cardBody[hidden]{display:none!important}.cardHeadSimple h2{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%}.cardChevron{display:grid;place-items:center;width:30px;height:30px;min-width:30px;min-height:30px;margin-left:2px;padding:0;border-radius:50%;color:var(--accent);font-size:17px;line-height:1;transform:rotate(180deg);transition:transform .16s ease,border-color .16s ease}.card.collapsed>.cardHead .cardChevron{transform:rotate(0deg)}
label{display:flex;justify-content:space-between;align-items:center;min-height:42px;margin:0;padding:8px 0;border-bottom:1px solid var(--line);font-size:12px;gap:12px;color:var(--text);min-width:0}label:last-child{border-bottom:0}
input[type=number],input[type=text],input[type=password],select{background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:8px 9px;font-size:11px}input[type=number]{width:102px}input[type=text],input[type=password],select{width:100%;margin-top:4px}label input[type=number]{flex:0 0 102px;margin-left:auto}label select{flex:1;min-width:170px}label input[type=checkbox]{margin-left:auto}input:focus,select:focus{outline:none;border-color:var(--accent);box-shadow:0 0 0 2px rgba(70,217,255,.08)}
input[type=checkbox]{appearance:none;-webkit-appearance:none;width:42px;height:23px;min-width:42px;border-radius:99px;border:1px solid var(--line2);background:#263541;position:relative;vertical-align:middle;cursor:pointer;transition:.18s}input[type=checkbox]:before{content:"";position:absolute;width:17px;height:17px;left:2px;top:2px;border-radius:50%;background:#b8c4cc;transition:.18s}input[type=checkbox]:checked{background:rgba(85,225,157,.28);border-color:var(--ok)}input[type=checkbox]:checked:before{left:21px;background:var(--ok);box-shadow:0 0 9px rgba(85,225,157,.5)}
input[type=file]{width:100%;background:var(--panel2);color:var(--text);border:1px dashed var(--line2);border-radius:7px;padding:12px;margin:8px 0 4px;font-size:11px}button:disabled{background:var(--panel3);color:var(--muted);border-color:var(--line);opacity:1;cursor:not-allowed}input:disabled{opacity:.5;cursor:not-allowed}
.profileDeck{position:relative;overflow:hidden;padding:18px;color:#edf5fb;background:linear-gradient(145deg,rgba(20,31,43,.98),rgba(11,18,25,.98))}.profileDeck:after{content:"";position:absolute;right:-80px;top:-90px;width:230px;height:230px;border-radius:50%;border:1px solid rgba(70,217,255,.12);box-shadow:0 0 0 38px rgba(70,217,255,.025),0 0 0 76px rgba(70,217,255,.018);pointer-events:none}.profileGrid{display:grid;grid-template-columns:1.2fr 1fr;gap:18px;position:relative;z-index:1}.eyebrow{color:#46d9ff;font-size:9px;font-weight:900;letter-spacing:.17em;text-transform:uppercase}.profileTitle{margin-top:7px;color:#edf5fb;font-size:24px;font-weight:950;letter-spacing:-.035em}.profileCopy{max-width:720px;margin-top:7px;color:#8ea4b5;font-size:11px;line-height:1.65}.profileSwitcher{display:grid;grid-template-columns:1fr 1fr;gap:8px;align-self:center}.profileChoice{min-height:88px;margin:0;padding:12px;text-align:left;border-radius:7px;color:#edf5fb;background:#0b1219;border-color:#243341}.profileChoice b,.profileChoice span,.profileChoice small{display:block}.profileChoice b{font-size:15px}.profileChoice span{margin-top:4px;color:#8ea4b5;font-size:10px}.profileChoice small{margin-top:8px;color:#46d9ff;font:9px Consolas,monospace}.profileChoice.active{border-color:var(--profile-accent,var(--accent));background:rgba(70,217,255,.08);box-shadow:inset 0 0 0 1px rgba(70,217,255,.15)}.profileChoice[data-fsd-profile="1"].active{background:rgba(169,137,255,.08)}
.profileMeta{flex-wrap:wrap;gap:7px;margin-top:13px}.profileBadge{padding:5px 8px;border-radius:5px;border:1px solid rgba(70,217,255,.3);color:#46d9ff;background:rgba(70,217,255,.055);font-size:9px;font-weight:850}.profileNote{color:#8ea4b5;font-size:10px}
.route-note{margin:8px 0;padding:9px;border-left:2px solid var(--accent);background:rgba(70,217,255,.055);color:var(--muted);font-size:10px;line-height:1.55}
.featureHelp{margin:5px 0 9px}.featureHelp summary{display:grid;place-items:center;width:24px;height:24px;list-style:none;border:1px solid var(--line2);border-radius:50%;background:var(--panel2);color:var(--accent);font-size:12px;font-weight:950;cursor:pointer;user-select:none}.featureHelp summary::-webkit-details-marker{display:none}.featureHelp[open] summary{border-color:var(--accent);box-shadow:0 0 0 2px rgba(70,217,255,.08)}.featureHelp div{margin-top:6px;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:var(--panel2);color:var(--muted);font-size:10px;line-height:1.6}.featureHelp b{color:var(--text)}
.cardTitle,.cardTitle>div{min-width:0}.featureHelpHeading{display:flex;align-items:center;gap:2px}.cardHead .featureHelpButton{position:relative;isolation:isolate;display:grid;place-items:center;flex:0 0 36px;width:36px;height:36px;min-height:36px;padding:0;border:0;border-radius:50%;font-size:12px;font-weight:700;color:var(--card-accent,var(--accent));background:transparent}.featureHelpButton::before{content:"";position:absolute;z-index:-1;left:50%;top:50%;width:22px;height:22px;transform:translate(-50%,-50%);border:1px solid var(--line2);border-radius:50%;pointer-events:none}.cardHead .featureHelpButton:hover::before,.featureHelpButton[aria-expanded="true"]::before{border-color:var(--card-accent,var(--accent));background:color-mix(in srgb,var(--card-accent,var(--accent)) 10%,transparent)}.featureHelpButton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.featureHelpPanel{margin:0 0 14px;padding:14px 16px;border:1px solid color-mix(in srgb,var(--card-accent,var(--accent)) 35%,var(--line));border-radius:12px;background:var(--panel2);color:var(--muted);font-size:12px;line-height:1.75;overflow-wrap:anywhere}.featureHelpPanel[hidden]{display:none!important}.featureHelpPanel>section+section{margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}.featureHelpPanel h3{margin:0 0 5px;padding:0;border:0;text-transform:none;letter-spacing:0;font-size:12px;color:var(--card-accent,var(--accent))}.featureHelpPanel .featureHelpCopy{margin:0;padding:0;border:0;background:transparent;font-size:inherit;line-height:inherit;color:inherit}.featureHelpPanel b{color:var(--text)}.featureHelpPanel ul{margin:6px 0 0;padding-left:20px}.featureHelpPanel li+li{margin-top:5px}.featureHelpPanel .kv{display:block}.featureHelpPanel .kv>span:first-child{display:none}html[data-ui-mode="car"] .cardHead .featureHelpButton{flex-basis:44px;width:44px;height:44px;min-height:44px;padding:0;font-size:14px}html[data-ui-mode="car"] .featureHelpButton::before{width:26px;height:26px}html[data-ui-mode="car"] .featureHelpPanel{font-size:14px}
.featureDesc{margin:-3px 0 6px;padding:0 0 7px;color:var(--muted);font-size:9px;line-height:1.55;border-bottom:1px solid var(--line)}.featureDesc+label{border-top:0}.fsdProtocolInputNote{margin:4px 0 10px;padding:8px 10px;border-radius:8px;background:var(--panel2);color:var(--muted);font-size:10px;line-height:1.55}
.presetHint{margin:7px 0 3px;padding:8px 10px;border-left:2px solid var(--accent2);background:rgba(169,137,255,.055);color:var(--muted);font-size:10px;line-height:1.55}.advancedSettings{margin-top:10px;border:1px solid var(--line);border-radius:7px;background:var(--panel2)}.advancedSettings>summary{padding:10px 12px;color:var(--accent2);font-size:11px;font-weight:850;cursor:pointer;user-select:none}.advancedSettings>div{padding:0 12px 11px}.advancedSettings h3:first-child{margin-top:2px}
html[data-theme="light"] .profileDeck{color:var(--text);background:linear-gradient(145deg,#fff,#eaf1f4)}html[data-theme="light"] .profileDeck:after{border-color:rgba(8,127,156,.14);box-shadow:0 0 0 38px rgba(8,127,156,.03),0 0 0 76px rgba(103,73,183,.02)}html[data-theme="light"] .profileTitle{color:var(--text)}html[data-theme="light"] .profileCopy,html[data-theme="light"] .profileNote{color:var(--muted)}html[data-theme="light"] .eyebrow{color:var(--accent)}html[data-theme="light"] .profileChoice{color:var(--text);background:var(--panel2);border-color:var(--line)}html[data-theme="light"] .profileChoice span{color:var(--muted)}html[data-theme="light"] .profileChoice small{color:var(--accent)}html[data-theme="light"] .profileChoice.active{background:rgba(8,127,156,.08);box-shadow:inset 0 0 0 1px rgba(8,127,156,.12)}html[data-theme="light"] .profileChoice[data-fsd-profile="1"].active{background:rgba(103,73,183,.08)}
.targetGrid{display:grid;grid-template-columns:1fr 1fr;column-gap:12px}.targetGrid label{min-width:0}.targetGrid label input{width:88px;flex-basis:88px}.profile-panel{animation:panelIn .18s ease}@keyframes panelIn{from{opacity:.55;transform:translateY(3px)}to{opacity:1;transform:none}}
.profileButtons{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin:8px 0 10px}.profileButtons.hw3StrategyButtons{grid-template-columns:repeat(3,minmax(0,1fr))}.profileButtons.speedSourceChoice{grid-template-columns:repeat(2,minmax(0,1fr))}.profileButtons button{width:100%;min-width:0;margin:0;padding:8px 4px;background:var(--panel2);color:var(--text);border-color:var(--line)}.profileButtons button.active{background:rgba(169,137,255,.18);color:var(--accent2);border-color:var(--accent2)}
.hw3StrategyButtons button{position:relative;display:flex;flex-direction:column;align-items:center;gap:2px;padding-bottom:12px}.hw3StrategyButtons button.editing{background:rgba(169,137,255,.18);color:var(--accent2);border-color:var(--accent2)}.hw3StrategyButtons button.active:not(.editing){background:var(--panel2);color:var(--text);border-color:var(--line)}.hw3StrategyButtons button b{font-size:11px}.hw3StrategyButtons button small{color:var(--muted);font-size:8px;font-weight:750}.hw3StrategyButtons button.active::after{content:"";position:absolute;left:25%;bottom:4px;width:50%;height:1px;border-radius:1px;background:var(--accent);box-shadow:0 0 5px color-mix(in srgb,var(--accent) 65%,transparent)}.hw3LiveMapping{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:4px 0 10px;padding:9px 11px;border:1px solid color-mix(in srgb,var(--accent) 40%,var(--line));border-radius:10px;background:color-mix(in srgb,var(--accent) 7%,var(--panel2));font-size:10px}.hw3LiveMapping span{color:var(--muted);font-weight:750}.hw3LiveMapping b{color:var(--accent);text-align:right}
.seatDeck{display:grid;grid-template-columns:1fr;gap:12px;margin-top:10px}.seatPanel{padding:13px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(145deg,var(--panel2),rgba(8,17,29,.7))}.seatPanel h3{margin:0 0 6px;padding:0;border:0}.seatSlots{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px;margin-top:9px}.seatSlot{padding:8px;border:1px solid var(--line);border-radius:9px;background:var(--panel)}.seatSlot.saved{border-color:rgba(85,225,157,.55);box-shadow:inset 0 0 0 1px rgba(85,225,157,.08)}.seatSlot b{display:block;margin-bottom:5px;color:var(--muted);font-size:9px}.seatSlot.saved b{color:var(--ok)}.seatSlot button{width:100%;min-height:31px;padding:5px 2px;margin-top:4px;font-size:9px}.seatStop{margin-top:10px}html[data-theme="light"] .seatPanel{background:var(--panel2)}
.seatSlotName{width:100%!important;margin:0 0 5px!important;padding:5px 6px!important;border-color:var(--line)!important;background:var(--panel2)!important;color:var(--muted)!important;font-size:10px!important;font-weight:800}.seatSlot.saved .seatSlotName{color:var(--ok)!important;border-color:rgba(85,225,157,.45)!important}.seatSlotName:focus{color:var(--text)!important;border-color:var(--accent)!important}
.seatManualHeading{margin-top:12px!important;padding-top:10px!important;border-top:1px solid var(--line)!important}.seatManualGrid{display:block}.seatAxisControl{display:grid;grid-template-columns:minmax(110px,.65fr) minmax(0,1.6fr);align-items:center;gap:10px;padding:9px 0;border:0;border-bottom:1px solid var(--line);border-radius:0;background:transparent}.seatAxisControl b{display:block;margin:0;color:var(--muted);font-size:10px}.seatAxisButtons{display:grid;grid-template-columns:1fr 1fr;gap:7px}.seatAxisButtons button{width:100%;min-height:38px;padding:7px 4px;touch-action:none;user-select:none;-webkit-user-select:none}.seatAxisButtons button.active{color:#07110c;border-color:var(--ok);background:var(--ok);box-shadow:0 0 14px rgba(85,225,157,.35)}
.gearMapGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}.gearMapGrid label{min-width:0}.gearMapGrid select{min-width:0}
.gearPrimaryGroup{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1fr) repeat(2,minmax(0,.9fr));gap:10px;padding:10px;border:1px solid var(--line);border-radius:7px;background:var(--panel2)}
.gearPrimaryGroup label{min-width:0;min-height:44px;padding:0;border:0}.gearPrimaryGroup select,.gearPrimaryGroup input[type=number]{width:100%;max-width:100%;min-width:0;min-height:44px;margin-top:0}.gearEnableControl{min-height:44px;padding:0 4px!important}#gearAutomationBody{margin-top:10px}#gearAutomationBody>.gearFeatureSwitch,#gearAutomationDiagnostics{margin-top:10px}.gearCooldownControl input{min-height:44px}.gearSmoothPreset{width:100%;max-width:100%;min-height:38px;margin-top:8px;color:var(--accent2)}
.gearActionGroups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:10px}.gearActionGroup{min-width:0;padding:10px;border:1px solid var(--line);border-radius:7px;background:var(--panel2)}.gearActionGroup h3{margin:0 0 6px;padding:0;border:0;color:var(--accent2)}.gearActionFields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.gearActionGroup label{display:block;min-width:0;min-height:0;padding:6px 0;border:0}.gearActionGroup select{width:100%;max-width:100%;min-width:0;min-height:44px}
