html.commercial #cloudRestoreDialog input[type=checkbox]{appearance:auto;-webkit-appearance:checkbox;display:block;position:static;box-sizing:border-box;flex:0 0 20px;width:20px;min-width:20px;max-width:20px;height:20px;min-height:20px;margin:0;padding:0;border:0;border-radius:4px;background:initial;accent-color:var(--accent);box-shadow:none}html.commercial #cloudRestoreDialog input[type=checkbox]:before,html.commercial #cloudRestoreDialog input[type=checkbox]:after{content:none;display:none}
html.commercial #cloudRestoreDialog .cloud-restore-confirm{padding:12px 0;background:none;border:0;font-weight:500;min-height:48px}#cloudRestoreMessage{color:var(--muted);font-size:12px;line-height:1.5}#cloudRestoreMessage.bad{color:var(--bad)}#cloudRestoreMessage:empty{display:none}#cloudRestoreDialog .cloud-actions{margin-top:12px}
@media(max-width:360px){.speed-quick-row{gap:6px}.speed-percent-field{flex-basis:66px}html.commercial .commercial-selected #speedTemplateQuickApply{padding:9px 8px;font-size:11px}html.commercial #cloudRestoreDialog{padding-left:16px;padding-right:16px}.cloud-v2-facts>div{padding:10px}}
@media(prefers-reduced-motion:reduce){html.commercial #hw3SpeedCard button,html.commercial #cloudSyncCard button{transition:none;transform:none}}

.onboarding-sheet{width:min(520px,100%);max-height:min(88vh,760px);overflow:auto}.onboarding-sheet h2{margin:0 0 10px;font-size:21px}.onboarding-sheet p{line-height:1.6}.onboarding-sheet label{display:grid;gap:6px;margin:12px 0}.onboarding-sheet textarea{width:100%;min-height:44px;resize:none}.onboarding-actions{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.onboarding-actions button{flex:1 1 125px;min-height:44px}.onboarding-device-id{display:flex;align-items:end;gap:8px}.onboarding-device-id label{flex:1;min-width:0}.onboarding-device-id textarea{width:100%;font:600 13px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}.onboarding-device-id button{min-height:44px;white-space:nowrap}#onboardingConnectWifi,#onboardingRestore{background:var(--accent);color:#fff;border:0}.cloud-website{display:grid;grid-template-columns:1fr auto;align-items:center;gap:8px;margin:10px 0}.cloud-website a{grid-column:1/-1;color:var(--accent);text-decoration:underline;min-height:30px}.cloud-website input{width:100%;min-width:0;min-height:40px;padding:8px;border:1px solid var(--line);border-radius:8px;background:var(--panel2);color:var(--text);font:12px ui-monospace,monospace}.cloud-website button{min-height:40px}.cloud-restore-progress{padding:10px;margin:8px 0;border-radius:9px;background:var(--panel2);font-size:12px;line-height:1.55;overflow-wrap:anywhere}.cloud-restore-progress[hidden]{display:none}
#onboardingDialog .onboarding-device-id{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:end;margin:16px 0}#onboardingDialog .onboarding-device-id label{display:grid;margin:0;gap:6px;width:auto;max-width:none}#onboardingDialog .onboarding-device-id textarea{box-sizing:border-box;width:100%;max-width:none;height:48px;min-height:48px;padding:12px;border:0;border-radius:12px;background:var(--panel2);color:var(--text);font:600 15px/24px ui-monospace,monospace}#onboardingDialog .onboarding-device-id button{margin:0;min-height:48px}#cloudRestoreScopeProgress,#cloudRestoreCardScopeProgress{white-space:pre-line}#cloudRestoreProgressBar,#cloudRestoreCardProgressBar{width:100%;height:10px;accent-color:var(--accent)}#cloudRestoreError,#cloudRestoreCardError{color:#c73737}
